from typing import Any
from tools.llm_client import ask_llm

POLICY_PROMPT = '''You are the Policy Agent. Use EC_POLICY_V2 and supplied evidence only. Do not invent IDs. Return exactly a valid final JSON object matching this required top-level schema: case_id, case_assessment, affected_entities, customer_context, product_context, delivery_analysis, payment_reconciliation, root_cause_analysis, evidence_ids, financial_resolution, resolution_actions. All arrays must be within assignment limits. Include only source-backed evidence IDs in exact allowed formats: order:<id>, item:<order>:<item>, payment:<order>:<seq>, seller:<id>, policy:<code>. Apply policy through reasoning; do not describe your reasoning.\n\nEC_POLICY_V2: priority: canceled paid=>canceled_order_paid/platform/full payment; unavailable paid=>unavailable_order_paid/platform/full payment; late delivered with seller handoff after shipping limit=>late_delivery_seller/refund freight; late delivered with no late seller=>late_delivery_logistics/refund freight; two or more payments with reconciled totals=>valid_split_payment/no refund; delivered not later with reconciled payment=>unsupported_late_claim/no refund. Secondary issues ordered: multi_item_order, multi_seller_order, split_payment, repeat_customer, multiple_categories. case_status action_required only if refund is recommended, otherwise no_action.'''

def run_policy_agent(context: dict[str, Any], customer: dict[str, Any], order_product: dict[str, Any], payment: dict[str, Any], delivery: dict[str, Any]) -> dict[str, Any]:
    return ask_llm(POLICY_PROMPT, {"context": context, "customer_agent": customer, "order_product_agent": order_product, "payment_agent": payment, "delivery_agent": delivery})
